def refs():
    return [{**s, "subject": "science", "locator": "複式顯微鏡倍率與操作、視野方向、洋蔥表皮與口腔上皮、細胞膜／細胞質／細胞核／細胞壁及比例尺", "observedPattern": "公立學校公開生物試題常用顯微鏡操作順序、倍率、影像方向與動植物細胞圖判讀；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-da-iv-1-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供顯微鏡操作、動植物細胞比較、構造辨識與比例尺判讀的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "第一次用複式顯微鏡觀察洋蔥表皮玻片時，最適合的起始操作是？", {"A": "先用低倍物鏡找完整、明亮的樣本，再調焦與換高倍觀察", "B": "直接使用最高倍物鏡並先轉粗調節輪", "C": "先拆下玻片，肉眼判斷細胞核", "D": "只調光圈，不需要確認樣本位置"}, "低倍視野較大、容易定位樣本，也較不易因焦距或玻片位置不準而找不到目標；找到後再逐步放大。", "依照定位—調焦—放大—細調的順序，避免一開始縮小可見範圍。", ["先選低倍物鏡取得較大視野。", "調整光線與粗調讓樣本出現在視野。", "確認細胞輪廓完整且位於適當位置。", "換高倍物鏡後只用細調改善清晰度。", "所以選 A。"], "easy"),
    make(2, "目鏡 10 倍、物鏡 40 倍時，複式顯微鏡的總倍率是多少？", {"A": "400 倍", "B": "50 倍", "C": "30 倍", "D": "4 倍"}, "複式顯微鏡總倍率＝目鏡倍率×物鏡倍率＝10×40＝400 倍。", "先確認兩個倍率都要相乘，不是相加或只取其中一個。", ["找出目鏡倍率 10 倍。", "找出物鏡倍率 40 倍。", "套用總倍率＝目鏡×物鏡。", "計算 10×40＝400。", "所以選 A。"], "easy"),
    make(3, "換成較高倍物鏡後，若光源與光圈不變，通常會出現哪種視野變化？", {"A": "可見範圍變小、亮度可能降低，需重新細調焦距", "B": "可見範圍變大且一定更亮", "C": "影像會自動變成實物正立方向", "D": "細胞數量增加且不必調焦"}, "高倍放大會縮小視野範圍，光線分布也可能使影像變暗；換倍率後通常需要重新細調焦距。", "分別檢查倍率對視野大小、亮度與焦距的影響。", ["比較低倍與高倍的放大程度。", "判斷視野中能涵蓋的範圍會縮小。", "注意相同光源下影像亮度可能下降。", "用細調節輪重新取得清晰影像。", "所以選 A。"], "medium"),
    make(4, "顯微鏡下的影像往左上方移動，若要讓它回到視野中央，玻片應往哪裡移？", {"A": "往左上方移動", "B": "往右下方移動", "C": "只轉動目鏡，不移動玻片", "D": "先換最高倍物鏡"}, "複式顯微鏡形成倒像，玻片的移動方向與影像在視野中的移動方向相同；影像往左上，玻片也往左上可把影像帶回中央。", "先固定題目所採的影像—玻片方向規則，再做相反或同向判讀，不能憑肉眼直覺。", ["讀出影像目前位於視野左上方。", "確認要把影像帶回中央。", "依複式顯微鏡倒像的移動關係判斷玻片方向。", "將玻片往左上方移動使影像回到中央。", "所以選 A。"], "hard"),
    make(5, "洋蔥表皮細胞呈現規則排列、外圍有較明顯硬直邊界；口腔上皮細胞則較不規則。哪項推論最合適？", {"A": "洋蔥表皮的外圍邊界可支持具有細胞壁，但仍要依影像和製片品質判讀", "B": "口腔上皮沒有細胞膜", "C": "規則排列就能證明所有細胞都有葉綠體", "D": "只要看顏色就能確定細胞核功能"}, "植物細胞通常具有細胞壁，規則外框可作為影像線索；但細胞構造判讀仍要考慮染色、倍率與影像品質。", "先說明直接看見的輪廓，再把構造判斷標記為有條件的推論。", ["比較兩種樣本的排列與邊界。", "將硬直外框視為植物細胞壁的支持線索。", "確認兩者仍都可能具有細胞膜、細胞質與細胞核。", "避免由排列規則直接推出葉綠體或功能。", "所以選 A。"], "medium"),
    make(6, "製作口腔上皮細胞臨時玻片時，滴加亞甲藍等染液的主要目的為何？", {"A": "增加部分構造與背景的對比，讓細胞核等構造較容易辨認", "B": "把動物細胞變成植物細胞", "C": "讓細胞立即產生葉綠體", "D": "提高顯微鏡物鏡的倍率"}, "染色是改善影像對比的處理，能幫助辨認原本透明或不明顯的構造，不會改變細胞種類或顯微鏡倍率。", "分清製片處理對影像可見度的作用與細胞本身構造。", ["確認口腔上皮細胞常較透明。", "辨認染液能改變的是顏色／對比。", "將細胞核等邊界較清楚的構造作比較。", "排除染液會產生葉綠體或改變物鏡倍率的說法。", "所以選 A。"], "easy"),
    make(7, "在沒有比例尺的顯微照片中，某細胞看起來比另一張照片大，最嚴謹的說法是？", {"A": "只能說照片中的影像較大，不能直接判定真實細胞較大", "B": "影像大就代表細胞真實尺寸一定大", "C": "兩張照片必然使用相同倍率", "D": "顯微鏡放大會改變細胞原本大小"}, "影像大小受倍率、裁切、螢幕顯示與距離影響；沒有倍率或比例尺時，不能直接比較真實尺寸。", "先找比例尺與倍率證據，再判斷能否從影像大小推回實際大小。", ["辨認題目沒有提供比例尺。", "列出倍率與影像顯示可能造成的差異。", "把照片中的視覺大小和真實尺寸分開。", "只有補上共同倍率或比例尺後才比較實際大小。", "所以選 A。"], "medium"),
    make(8, "下列哪一組構造最可能同時出現在植物與動物的真核細胞？", {"A": "細胞膜、細胞質與細胞核", "B": "細胞壁、葉綠體與細胞核", "C": "葉綠體、液泡與細胞壁", "D": "細胞壁、鞭毛與葉綠體"}, "植物與動物細胞都可具有細胞膜、細胞質和細胞核；細胞壁與葉綠體是植物細胞常用來比較的特有構造。", "先找兩類細胞的共同基本構造，再排除只在特定細胞出現的構造。", ["列出植物與動物細胞都需要的基本邊界和內部構造。", "確認細胞膜、細胞質與細胞核符合共同項目。", "辨認細胞壁與葉綠體是植物比較的重要差異。", "檢查每個選項是否混入只屬一類的構造。", "所以選 A。"], "easy"),
    make(9, "顯微鏡下只看見一團深色區域，沒有清楚的邊界或染色對照。應如何記錄？", {"A": "記下觀察到深色區域，但暫不武斷命名為細胞核，並註明證據不足", "B": "所有深色區域都一定是細胞核", "C": "直接把它標成葉綠體", "D": "刪除這筆觀察，因為看不清就不能記錄"}, "科學紀錄要區分直接觀察與推論；缺乏邊界、染色或對照時，應保留不確定性並記錄限制。", "採用『看見什麼—推測什麼—還缺什麼』三欄記錄。", ["描述可直接看見的深色區域。", "檢查是否有細胞核的邊界或染色證據。", "把名稱判斷暫列為待確認推論。", "記錄需要重新調焦、染色或換樣本來驗證。", "所以選 A。"], "hard"),
    make(10, "觀察報告要比較洋蔥表皮與口腔上皮，哪種寫法最完整？", {"A": "分別記錄樣本、倍率、排列與可見構造，再區分直接觀察、功能推論與影像限制", "B": "只貼兩張照片，不記錄倍率和樣本來源", "C": "只寫植物細胞比較大，因為照片看起來較大", "D": "把所有看不見的構造都記成不存在"}, "完整報告必須讓讀者知道樣本、觀察條件和證據，並把功能推論與影像限制分開，避免由照片外觀過度推論。", "用樣本—條件—觀察—推論—限制五欄回查報告。", ["寫明洋蔥表皮與口腔上皮的樣本來源。", "記錄目鏡、物鏡與觀察條件。", "逐項描述邊界、排列和可見構造。", "把構造功能和影像限制另外標示。", "所以選 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
